from pathlib import Path
import subprocess

ROOT = Path.cwd()
head = subprocess.check_output(['git','rev-parse','--short','HEAD'], text=True).strip()
if not head.startswith('b0782eb'):
    raise SystemExit(f'Expected HEAD b0782eb, found {head}')

def read(rel):
    return (ROOT / rel).read_text(encoding='utf-8')

def write(rel, text):
    (ROOT / rel).write_text(text, encoding='utf-8')

write('components/admin/admin-entitlement-submit.tsx', '"use client";\n\nimport {\n  useEffect,\n  useRef,\n  useState,\n} from "react";\n\nexport type AdminSaveFeedback = {\n  tone: "success" | "error";\n  message: string;\n};\n\ntype ServerFormAction = (\n  formData: FormData,\n) => Promise<unknown>;\n\nexport function useAdminEntitlementSubmit(\n  initialEnabled: Record<string, boolean>,\n) {\n  const [enabledByKey, setEnabledByKey] =\n    useState<Record<string, boolean>>(\n      initialEnabled,\n    );\n\n  const [pendingKey, setPendingKey] =\n    useState<string | null>(null);\n\n  const [feedbackByKey, setFeedbackByKey] =\n    useState<\n      Record<\n        string,\n        AdminSaveFeedback | undefined\n      >\n    >({});\n\n  const timers = useRef<\n    Record<string, number>\n  >({});\n\n  useEffect(() => {\n    return () => {\n      for (const timer of Object.values(\n        timers.current,\n      )) {\n        window.clearTimeout(timer);\n      }\n    };\n  }, []);\n\n  function clearFeedbackLater(\n    key: string,\n  ) {\n    const existing = timers.current[key];\n\n    if (existing) {\n      window.clearTimeout(existing);\n    }\n\n    timers.current[key] =\n      window.setTimeout(() => {\n        setFeedbackByKey((current) => {\n          const next = { ...current };\n          delete next[key];\n          return next;\n        });\n\n        delete timers.current[key];\n      }, 5000);\n  }\n\n  async function submit(\n    key: string,\n    formData: FormData,\n    action: ServerFormAction,\n    successMessage = "Saved.",\n  ) {\n    const existing = timers.current[key];\n\n    if (existing) {\n      window.clearTimeout(existing);\n      delete timers.current[key];\n    }\n\n    setPendingKey(key);\n    setFeedbackByKey((current) => {\n      const next = { ...current };\n      delete next[key];\n      return next;\n    });\n\n    try {\n      await action(formData);\n\n      const enabled =\n        String(\n          formData.get("enabled") ??\n            "false",\n        ) === "true";\n\n      setEnabledByKey((current) => ({\n        ...current,\n        [key]: enabled,\n      }));\n\n      setFeedbackByKey((current) => ({\n        ...current,\n        [key]: {\n          tone: "success",\n          message: successMessage,\n        },\n      }));\n\n      window.dispatchEvent(\n        new CustomEvent(\n          "sepulchria:admin-data-changed",\n        ),\n      );\n\n      clearFeedbackLater(key);\n    } catch (error) {\n      setFeedbackByKey((current) => ({\n        ...current,\n        [key]: {\n          tone: "error",\n          message:\n            error instanceof Error\n              ? error.message\n              : "Unable to save changes.",\n        },\n      }));\n\n      clearFeedbackLater(key);\n    } finally {\n      setPendingKey((current) =>\n        current === key ? null : current,\n      );\n    }\n  }\n\n  return {\n    enabledByKey,\n    pendingKey,\n    feedbackByKey,\n    submit,\n  };\n}\n\nexport function AdminSaveFeedbackMessage({\n  feedback,\n}: {\n  feedback:\n    | AdminSaveFeedback\n    | undefined;\n}) {\n  if (!feedback) return null;\n\n  return (\n    <span\n      role={\n        feedback.tone === "error"\n          ? "alert"\n          : "status"\n      }\n      className={\n        feedback.tone === "success"\n          ? "text-[9px] uppercase tracking-[0.14em] text-[rgb(var(--sep-colour-a8cf92))]"\n          : "text-[9px] uppercase tracking-[0.14em] text-[rgb(var(--sep-colour-d89486))]"\n      }\n    >\n      {feedback.message}\n    </span>\n  );\n}\n')

# 1) Make the right-side navigator resilient and give missing nodes stable IDs.
rel = 'components/admin/admin-character-premium-features-context.tsx'
text = read(rel)
old = '      setEntries(\n        nodes.map((node) => ({\n          id: node.id,\n          name:\n            node.dataset.adminFeatureName ??\n            "Unnamed feature",\n          type:\n            node.dataset.adminFeatureType ??\n            "Feature",\n        })),\n      );\n'
new = '      setEntries(\n        nodes.map((node, index) => {\n          const id =\n            node.id.trim() ||\n            `admin-premium-feature-${index}`;\n\n          if (!node.id) {\n            node.id = id;\n          }\n\n          return {\n            id,\n            name:\n              node.dataset.adminFeatureName ??\n              "Unnamed feature",\n            type:\n              node.dataset.adminFeatureType ??\n              "Feature",\n          };\n        }),\n      );\n'
if old not in text:
    raise SystemExit('Navigator entry mapping block not found')
text = text.replace(old, new, 1)
write(rel, text)

